import * as T from './vendor/three.js';
// A local high-dynamic-range studio/sky field supplies soft reflections without external assets.
export function createEnvironment(renderer){const w=256,h=128,data=new Float32Array(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const u=x/w,v=y/h;const sky=Math.max(0,Math.sin(v*Math.PI));const softbox=Math.exp(-((u-.23)**2/.003+(v-.65)**2/.012))*3;const rim=Math.exp(-((u-.75)**2/.009+(v-.6)**2/.02))*1.4;const i=(y*w+x)*4;data[i]=.22+sky*.48+softbox+rim*.75;data[i+1]=.24+sky*.53+softbox*.95+rim*.9;data[i+2]=.27+sky*.61+softbox*.83+rim;data[i+3]=1}const source=new T.DataTexture(data,w,h,T.RGBAFormat,T.FloatType);source.mapping=T.EquirectangularReflectionMapping;source.needsUpdate=true;const generator=new T.PMREMGenerator(renderer),environment=generator.fromEquirectangular(source);source.dispose();generator.dispose();return environment}
